import{_ as t,o,c as s,a2 as i}from"./chunks/framework.CyZTVJbV.js";const y=JSON.parse('{"title":"OIDC Federation Dogfood — discovery-jwks-skeleton quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/oidc-federation-discovery.md","filePath":"quality-reports/auth/oidc-federation-discovery.md"}'),a={name:"quality-reports/auth/oidc-federation-discovery.md"};function r(d,e,n,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="oidc-federation-dogfood-—-discovery-jwks-skeleton-quality-report" tabindex="-1">OIDC Federation Dogfood — discovery-jwks-skeleton quality report <a class="header-anchor" href="#oidc-federation-dogfood-—-discovery-jwks-skeleton-quality-report" aria-label="Permalink to &quot;OIDC Federation Dogfood — discovery-jwks-skeleton quality report&quot;">​</a></h1><p>Skeleton report for <code>examples/dogfood-oidc-federation</code> Sub-Issue #872 (v1.21-4a).</p><p>Full mock vs real fidelity numbers are filled in as DCR / id_token verify / federation / rotation e2e land in Sub-Issues #873 - #875. This report tracks the discovery-JWKS-skeleton phase only — the OP exposes <code>.well-known/openid-configuration</code> + <code>/jwks</code> + <code>/jwks/rotate</code> with the shape enforced by RFC 7517 / OIDC Discovery §3, but authorize / token / userinfo remain delegated to the underlying kiwa OP layer that Sub-Issue #874 will surface.</p><h2 id="fidelity-axes-discovery-jwks-skeleton" tabindex="-1">Fidelity axes (discovery-jwks-skeleton) <a class="header-anchor" href="#fidelity-axes-discovery-jwks-skeleton" aria-label="Permalink to &quot;Fidelity axes (discovery-jwks-skeleton)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>axis</th><th>mock (<code>@kiwa-lab/auth</code>)</th><th>real (Keycloak + testcontainers)</th><th>assertion</th></tr></thead><tbody><tr><td>1. discovery metadata</td><td>Static shape derived from <code>issuer</code>; response_types=[code], id_token_signing_alg_values=[RS256, ES256], code_challenge_methods=[S256], scopes_supported=[openid, profile, email, offline_access], token_endpoint_auth_methods=[client_secret_basic, client_secret_post, none]</td><td>Keycloak realm boot-time metadata; issuer is derived from <code>KEYCLOAK_URL</code> env var Sub-Issue #873 will set</td><td>OIDC Discovery §3 mandatory keys present + OAuth 2.1 restrictions honoured (implicit + plain PKCE + password grants explicitly omitted).</td></tr><tr><td>2. discovery issuer 一致 guard</td><td><code>assertIssuerMatchesFetchUrl</code> throws <code>DiscoveryIssuerMismatchError</code> when metadata.issuer diverges from fetch URL; trailing-slash tolerant</td><td>Same guard runs against Keycloak realm URL</td><td>OIDC Discovery §4.3 — <code>issuer</code> MUST equal URL used to fetch.</td></tr><tr><td>3. JWKS active key shape</td><td>Exactly one active key (retiredAt undefined); RS256 keys satisfy kty=RSA + n + e; ES256 keys satisfy kty=EC + crv=P-256 + x + y; every key carries <code>use=sig</code> + non-empty kid matching <code>/^k\\d{3}$/</code></td><td>Keycloak <code>/certs</code> emits the same shape per RFC 7517 §4</td><td>Mandatory JWK fields present per alg family; downstream verifiers can pick the active key without walking a heuristic.</td></tr><tr><td>4. JWKS rotation retention</td><td><code>rotate()</code> mints fresh kid; previous key gets <code>retiredAt = now + retentionSec</code>; retired keys stay in document until <code>now &gt; retiredAt</code>; rotate preserves alg family (RS256 stays RS256)</td><td>Keycloak key rotation policy honours the same retention window</td><td>Downstream verifiers accept id_tokens signed under retired kid until the window elapses; window controls the maximum gap between rotation and forced re-sign.</td></tr></tbody></table><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><ul><li><code>tests/discovery-jwks-skeleton.spec.ts</code> — 21 tests, split into six describe blocks: <ul><li><code>axis 1 — discovery metadata shape</code> — 4 tests covering mandatory OIDC §3 fields + OAuth 2.1 restrictions + real static shape + mock vs real diff.</li><li><code>axis 2 — discovery issuer 一致 guard</code> — 4 tests covering pass path + mismatch throw + trailing-slash tolerance + real static-shape guard.</li><li><code>axis 3 — JWKS active key shape</code> — 5 tests covering active key shape + <code>use=sig</code> + kid pattern + RS256/ES256 shape guards + real env-missing refuse.</li><li><code>axis 4 — JWKS rotation retention</code> — 5 tests covering rotate mints fresh kid + alg-family stability + retention window drop + three-rotation kid distinctness + real refuse.</li><li><code>real adapter — env-missing skeleton</code> — 4 tests validating <code>KIWA_OIDC_ENV_MISSING</code> gate + discovery-still-works static shape + KIWA_MODE=mock override + partial env vars (OIDC_BOOTSTRAP without KEYCLOAK_URL) still refuse.</li><li><code>DCR skeleton</code> — 3 tests validating mock DCR endpoint (basic success + empty redirect_uris refuse + distinct client_id generation).</li></ul></li></ul><p>Coverage target for the skeleton is <strong>structural</strong> — Sub-Issue #872 lands the shared surface + KIWA_MODE split; behavioural coverage on the underlying OIDC helper live inside <code>packages/auth/tests/setup-oidc-env.test.ts</code> (35 tests, 93.5% line coverage per PR #855).</p><h2 id="environment-gating" tabindex="-1">Environment gating <a class="header-anchor" href="#environment-gating" aria-label="Permalink to &quot;Environment gating&quot;">​</a></h2><ul><li><code>KIWA_MODE=mock</code> — forces the mock adapter; every test always runs.</li><li><code>OIDC_BOOTSTRAP=1</code> — opt-in for real ceremonies. Sub-Issue #873 will wire Keycloak through testcontainers behind this gate.</li><li>Without <code>OIDC_BOOTSTRAP=1</code>, the real adapter&#39;s <code>discovery()</code> returns a valid metadata document (static shape derived from <code>issuer</code>); every other method reports <code>KIWA_OIDC_ENV_MISSING</code>.</li></ul><h2 id="what-lands-in-the-successors" tabindex="-1">What lands in the successors <a class="header-anchor" href="#what-lands-in-the-successors" aria-label="Permalink to &quot;What lands in the successors&quot;">​</a></h2><ul><li><strong>Sub-Issue #873 (v1.21-4b — DCR)</strong> wires the DCR endpoint through Keycloak <code>/registrations</code>; the fidelity harness grows to 8 axes (4 skeleton + 4 DCR: auth method 3 種 / dropped grant refuse / software_statement JWS / redirect_uri validation).</li><li><strong>Sub-Issue #874 (v1.21-4c — id_token)</strong> lands the Nuxt 3 RP + authorization code flow + id_token verify (JWS + claims + nonce + hash chain); fidelity harness grows to 12 axes.</li><li><strong>Sub-Issue #875 (v1.21-4d — Federation + rotation e2e)</strong> lands the trust chain (3-level resolve + cycle detect + expiry) + JWKS rotation e2e (id_token signed under old kid stays verifiable until retention window elapses) + real Keycloak fidelity + release gate 7 axes + integrated docs. Fidelity harness caps out at 16 axes.</li></ul>',12)])])}const p=t(a,[["render",r]]);export{y as __pageData,p as default};
